function initialForm(date=state.filterDate){return {case_number:'',session_date:date,session_time:'08:00',plaintiffs:'',defendants:'',case_type:'',claim_summary:'',claim_requests:'',stage:'followup',previous_date:'',previous_minutes:'',last_session_summary:'',adjournment_reason:'',reason_evidence_quote:'',next_action:'',summary_warning:'',summary_mode:'manual',status:'draft'};}
const statusTitle = (v)=>({draft:'مسودة',ready:'بانتظار الاعتماد',approved:'معتمدة'}[v]||'مسودة');
