function isReportApproved(){return !!state.reportApprovals.find(r=>r.session_date===state.filterDate&&r.approved_at);}
async function approveReport(){if(!isJudge())return notify('اعتماد التقرير متاح للقاضي فقط.','error');const all=listForDate();if(!all.length||all.some(x=>x.status!=='approved'))return notify('اعتمد جميع ملخصات القضايا أولًا.','error');if(!confirm('هل راجعت قضايا هذا التاريخ وتريد اعتماد التقرير قبل حفظ صورته؟'))return;
 try{if(DEMO){state.reportApprovals=state.reportApprovals.filter(x=>x.session_date!==state.filterDate);state.reportApprovals.push({session_date:state.filterDate,approved_at:new Date().toISOString(),approved_by:actorId(),case_count:all.length});demoEvent(`${state.profile.display_name} اعتمد تقرير جلسات ${state.filterDate}`);render();return;}const {error}=await state.client.from('report_approvals').upsert({session_date:state.filterDate,approved_at:new Date().toISOString(),case_count:all.length},{onConflict:'session_date'});if(error)throw error;await loadAll();notify('تم اعتماد التقرير ويمكن حفظ الصورة.','success');}catch(e){notify('تعذّر اعتماد التقرير: '+e.message,'error');}}
function render(){if(!app)return;if(DEMO&&!state.profile){app.innerHTML=selectUserScreen();return;}if(!DEMO&&!state.user){app.innerHTML=authScreen();return;}if(!DEMO&&!state.profile?.is_active){app.innerHTML=pendingScreen();return;}app.innerHTML=shell();}
function selectUserScreen(){return `<div class="choose-screen"><div class="choose-header"><span class="choose-emblem">▦</span><span>تنظيم أعمال الدائرة الرابعة</span></div><div class="choose-card"><div class="eyebrow">مساحة العمل المشتركة</div><h1>مرحبًا بك</h1><p>اختر اسمك للدخول إلى الواجهة التجريبية، وسيظهر اسمك بجانب ما أضفته من قضايا أو مهام.</p><div class="staff-grid">${STAFF.map(p=>`<button data-person="${esc(p.id)}" class="staff-choice"><span class="staff-avatar">${esc(p.display_name[0])}</span><span><b>${esc(p.display_name)}</b><small>${roleTitle(p.role)}</small></span><span class="staff-arrow">←</span></button>`).join('')}</div><div class="selector-notice">اختيار الاسم هنا للتجربة فقط ولا يثبت هوية الشخص؛ بعد ربط قاعدة البيانات يستخدم الدخول بلا كلمة مرور عبر رابط البريد مرة واحدة على كل جهاز. لا تُدخل بيانات قضايا حقيقية في وضع المعاينة.</div></div><div class="choose-foot">تصميم مستقل مستوحى من الطابع الإداري الأخضر، دون شعارات أو انتماء مؤسسي.</div></div>`;}
function authScreen(){return `<div class="choose-screen"><div class="choose-header"><span class="choose-emblem">▦</span><span>تنظيم أعمال الدائرة الرابعة</span></div><div class="choose-card auth-choice"><div class="eyebrow">دخول بدون كلمة مرور</div><h1>الدخول إلى مساحة العمل</h1><p>اختر اسمك ثم اطلب رابط الدخول إلى بريدك المرتبط بحسابك المفعّل. بعد التحقق سيبقى الدخول محفوظًا على جهازك.</p><div class="staff-grid">${STAFF.map(p=>`<button data-person="${esc(p.id)}" class="staff-choice ${state.selectedPerson===p.id?'person-selected':''}"><span class="staff-avatar">${esc(p.display_name[0])}</span><span><b>${esc(p.display_name)}</b><small>${roleTitle(p.role)}</small></span><span class="staff-arrow">${state.selectedPerson===p.id?'✓':'←'}</span></button>`).join('')}</div><form id="auth-form" class="login-bottom"><label class="form-label">بريد الحساب المخصص لك</label><input class="input" name="email" type="email" autocomplete="email" placeholder="name@example.com" required value="${esc(state.authEmail)}"/><button class="btn btn-primary" type="submit" ${!state.selectedPerson?'disabled':''}>${state.authBusy?'جارٍ الإرسال...':'إرسال رابط الدخول'}</button>${state.loginSent?'<div class="selector-notice">أُرسل رابط الدخول إن كان البريد مسجلًا. افتح رسالة البريد في هذا الجهاز لإكمال الدخول.</div>':''}<p class="hint">اختيار الاسم وحده لا يمنح صلاحية دخول أو يسمح بانتحال الاسم؛ يلزم تأكيد ملكية البريد لحماية أعمال الدائرة.</p></form></div></div>`;}
function pendingScreen(){return `<div class="auth-screen"><div class="auth-art"><h1>تنظيم أعمال الدائرة الرابعة</h1><p>بيانات القضايا محمية بصلاحيات محددة.</p></div><div class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">الحساب قيد المراجعة</div><h2>بانتظار تفعيل الحساب</h2><p>تم تسجيل الحساب، لكن لم تُعتمد صلاحية الوصول حتى الآن. يُفعّل المشرف الحساب من قاعدة البيانات.</p><button class="btn" data-action="refresh-profile">التحقق مجددًا</button><button class="text-button" data-action="logout">تسجيل الخروج</button></div></div></div>`;}
function openEditor(id='new'){state.detailId=null;state.showSource=false;state.editorId=id;state.form=id==='new'?initialForm():{...state.cases.find(x=>x.id===id)};render();}
function closeModal(){state.detailId=null;state.editorId=null;state.form=null;state.showSource=false;render();}
function localSummarize(text){const normalized=(text||'').replace(/\r/g,'').trim();if(!normalized)return {last_session_summary:'',adjournment_reason:'',reason_evidence_quote:'',next_action:'',summary_warning:'أدخل ضبط الجلسة أولًا.'};const sentences=normalized.split(/(?<=[.؛؟\n])\s*|(?=ثم\s+قررت\s+الدائرة)|(?=وقررت\s+الدائرة)/).map(s=>s.trim()).filter(Boolean);const match=sentences.filter(s=>/رفعت\s+الجلسة|تأجيل\s+الجلسة|تأجيلها|أجلت\s+الجلسة|للرد|إمهال|طلب\s+مهلة|ندب\s+خبير|إحضار\s+بينة|لحضور|انتظار\s+ورود/.test(s));const evidence=match.find(s=>/رفعت\s+الجلسة|أجلت\s+الجلسة|تأجيل\s+الجلسة|تأجيلها/.test(s))||'';const exact=evidence&&normalized.includes(evidence)?evidence:'';const reason=exact?'راجع العبارة الحرفية التالية وحدد السبب الصريح الوارد فيها، دون استنتاج: '+short(exact,330):'لم يرد في النص المستخرج سبب صريح يمكن تأكيده آليًا.';const action=match.find(s=>/الجلسة\s+القادمة|إحضار|تقديم\s+مذكرة|الرد|تقرير\s+الخبير/.test(s));return {last_session_summary:short(normalized,510),adjournment_reason:reason,reason_evidence_quote:exact,next_action:action?short(action,240):'لم يُحدد الإجراء القادم صراحة في الاستخراج الآلي.',summary_warning:'استخراج أولي قائم على النص، وليس فهمًا قضائيًا معتمدًا؛ تحقق من الضبط الأصلي والاقتباس قبل اعتماد سبب الرفع.'};}
function validateForm(){const f=state.form;if(!f.case_number?.trim()||!f.session_date||!f.session_time||!f.plaintiffs?.trim()||!f.defendants?.trim()||!f.case_type?.trim()){notify('أكمل رقم القضية وموعدها وأطرافها ونوع الدعوى.','error');return false;}if(f.reason_evidence_quote?.trim()&&!f.previous_minutes?.includes(f.reason_evidence_quote.trim())){notify('اقتباس سبب الرفع غير موجود حرفيًا في نص الضبط. عدّل الاقتباس أو احذفه.','error');return false;}if(state.cases.some(c=>c.id!==state.editorId&&c.case_number===f.case_number.trim()&&c.session_date===f.session_date)){notify('القضية مدخلة بالفعل في هذا التاريخ، افتحها للتعديل.','error');return false;}return true;}
async function saveCase(status='ready'){if(!validateForm())return;const f={...state.form};const allowable=['case_number','session_date','session_time','plaintiffs','defendants','case_type','claim_summary','claim_requests','stage','previous_date','previous_minutes','last_session_summary','adjournment_reason','reason_evidence_quote','next_action','summary_warning','summary_mode'];const payload=Object.fromEntries(allowable.map(k=>[k, typeof f[k]==='string'?f[k].trim():f[k]]));payload.previous_date=payload.previous_date||null;payload.status=status==='approved'?'approved':status;payload.updated_by=actorId();if(status==='approved'){if(state.profile?.role!=='judge'){notify('الاعتماد متاح للقاضي فقط.','error');return;}if(payload.stage!=='first'&&!payload.previous_minutes){notify('لا يمكن اعتماد متابعة دون نص الضبط.','error');return;}}if(state.editorId==='new')payload.created_by=actorId();state.loading=true;try{if(DEMO){let isNew=state.editorId==='new';const old=state.cases.find(c=>c.id===state.editorId);const doc={...old,...payload,id:isNew?uid():state.editorId,created_at:old?.created_at||new Date().toISOString(),updated_at:new Date().toISOString(),created_by:old?.created_by||actorId()};if(old?.status==='approved'&&JSON.stringify(payload)!==JSON.stringify(Object.fromEntries(Object.keys(payload).map(k=>[k,old[k]])))&&status!=='approved')doc.status='ready';if(status==='approved')doc.approved_by=actorId();state.cases=isNew?[...state.cases,doc]:state.cases.map(x=>x.id===doc.id?doc:x);state.reportApprovals=state.reportApprovals.filter(r=>![doc.session_date,old?.session_date].includes(r.session_date));demoEvent(`${state.profile.display_name} ${isNew?'أضاف':'عدّل'} القضية ${doc.case_number}`);notify('تم الحفظ محليًا في هذه المعاينة.','success');closeModal();return;}let query=state.client.from('cases');let result=state.editorId==='new'?await query.insert(payload).select('id').single():await query.update(payload).eq('id',state.editorId).select('id').single();if(result.error)throw result.error;notify(status==='approved'?'حُفظت القضية واعتمدت.':'حُفظت القضية وظهرت في الحسابات المشتركة.','success');closeModal();await loadAll();}catch(err){notify('تعذّر الحفظ: '+err.message,'error');}finally{state.loading=false;}}
async function approveCase(id){if(!isJudge())return;const c=state.cases.find(x=>x.id===id);if(!c)return;if(c.stage!=='first'&&!c.previous_minutes){notify('يجب حفظ الضبط الأصلي قبل الاعتماد.','error');return;}if(c.reason_evidence_quote&&!c.previous_minutes.includes(c.reason_evidence_quote)){notify('الاقتباس لا يطابق الضبط الأصلي.','error');return;}if(!window.confirm('هل راجعت الملخص وسبب رفع الجلسة بالرجوع إلى الضبط الأصلي؟'))return;if(DEMO){c.status='approved';c.approved_by=actorId();c.updated_at=new Date().toISOString();state.reportApprovals=state.reportApprovals.filter(r=>r.session_date!==c.session_date);demoEvent(`${state.profile.display_name} اعتمد القضية ${c.case_number}`);closeModal();return;}const {error}=await state.client.from('cases').update({status:'approved',approved_by:state.user.id,updated_by:state.user.id}).eq('id',id);if(error)return notify('فشل الاعتماد: '+error.message,'error');notify('تم اعتماد الملخص','success');closeModal();await loadAll();}
async function softDeleteCase(){const id=state.editorId;if(id==='new')return;if(!window.confirm('هل تريد إزالة هذه القضية من الجدول؟ ستبقى نسخة في سجل المراجعات.'))return;if(DEMO){const c=state.cases.find(x=>x.id===id);state.cases=state.cases.filter(x=>x.id!==id);state.reportApprovals=state.reportApprovals.filter(r=>r.session_date!==c?.session_date);demoEvent(`${state.profile.display_name} أزال القضية ${c?.case_number||''}`);notify('أُزيلت القضية من المعاينة.','success');closeModal();return;}const {error}=await state.client.from('cases').update({deleted_at:new Date().toISOString(),updated_by:state.user.id}).eq('id',id);if(error)return notify(error.message,'error');notify('أُزيلت القضية من العرض.','success');closeModal();await loadAll();}
async function summarizeAI(){if(DEMO||!CONFIG.aiEnabled)return;const text=state.form.previous_minutes?.trim();if(!text)return notify('الصق ضبط الجلسة أولًا','error');notify('جارٍ طلب التلخيص من الوظيفة الآمنة...');try{const {data,error}=await state.client.functions.invoke('summarize-minutes',{body:{text}});if(error)throw error;if(data?.error)throw Error(data.error);if(data.reason_evidence_quote&&!text.includes(data.reason_evidence_quote))throw Error('النص الداعم غير مطابق؛ لم يتم اعتماد ناتج الذكاء الاصطناعي');for(const k of ['last_session_summary','adjournment_reason','reason_evidence_quote','next_action','summary_warning'])state.form[k]=data[k]||'';state.form.summary_mode='ai';render();notify('تم توليد الملخص، راجعه قبل الحفظ.','success');}catch(e){notify('تعذر التلخيص الذكي: '+e.message,'error');}}
async function loadProfile(){const {data,error}=await state.client.from('profiles').select('*').eq('id',state.user.id).maybeSingle();if(error)throw error;state.profile=data||null;}
async function loadAll(){if(DEMO){render();return;}if(!state.profile?.is_active)return;
 const [cases,notifications,profiles,tasks,reports]=await Promise.all([
  state.client.from('cases').select('*').is('deleted_at',null).order('session_date',{ascending:true}),
  state.client.from('notifications').select('*').eq('recipient_id',state.user.id).order('created_at',{ascending:false}).limit(90),
  state.client.from('profiles').select('id,display_name,role').eq('is_active',true),
  state.client.from('tasks').select('*').is('deleted_at',null).order('created_at',{ascending:false}),
  state.client.from('report_approvals').select('*')]);
 if(cases.error)notify('تعذّر تحديث القضايا: '+cases.error.message,'error');else state.cases=cases.data||[];
 if(tasks.error)notify('تعذّر تحديث المهام: '+tasks.error.message,'error');else state.tasks=tasks.data||[];
 if(reports.error)console.warn('Report approvals:',reports.error);else state.reportApprovals=reports.data||[];
 if(notifications.error)console.warn('Notifications:',notifications.error);else {
  const oldIds=new Set(state.notifications.map(n=>n.id)),next=notifications.data||[];
  if(!state.initialNotifLoad){for(const x of next){if(!oldIds.has(x.id)&&!x.read_at&&'Notification' in window && Notification.permission==='granted'&&document.visibilityState==='hidden'){try{new Notification('تنظيم أعمال الدائرة الرابعة',{body:x.message,icon:'assets/favicon.svg'});}catch{}}}}
  state.notifications=next;state.initialNotifLoad=false;
 }
 if(!profiles.error)state.profiles=profiles.data||[];render();}
async function refreshProfile(){try{await loadProfile();if(state.profile?.is_active)await loadAll();else render();}catch(e){notify(e.message,'error');}}
async function init(){if(DEMO){const d=safeStored('fourth-circuit-demo-v2');if(d){state.cases=d.cases||[];state.tasks=d.tasks||[];state.notifications=d.notifications||[];state.reportApprovals=d.reportApprovals||[];}else persistDemo();const chosen=localStorage.getItem('fourth-circuit-demo-profile');state.profile=STAFF.find(p=>p.id===chosen)||null;render();return;}try{const mod=await import('https://esm.sh/@supabase/supabase-js@2.119.0?bundle');state.client=mod.createClient(CONFIG.supabaseUrl,CONFIG.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true}});const {data:{session},error}=await state.client.auth.getSession();if(error)throw error;state.user=session?.user||null;if(state.user){await loadProfile();if(state.profile?.is_active){await loadAll();subscribeChanges();}}state.client.auth.onAuthStateChange((_ev,session)=>{const old=state.user?.id;state.user=session?.user||null;if(state.user?.id!==old){if(state.sub){state.client.removeChannel(state.sub);state.sub=null;}state.profile=null;state.notifications=[];state.initialNotifLoad=true;render();if(state.user){setTimeout(async()=>{await refreshProfile();if(state.profile?.is_active)subscribeChanges();},10);}}});render();}catch(e){app.innerHTML=`<div class="empty" style="min-height:90vh"><b>تعذّر تشغيل الموقع</b><p>${esc(e.message)}. تحقق من بيانات الاتصال بالقاعدة والاتصال بالإنترنت.</p></div>`;}}
function subscribeChanges(){if(state.sub)return;state.sub=state.client.channel('case-team-sync').on('postgres_changes',{event:'*',schema:'public',table:'cases'},()=>loadAll()).on('postgres_changes',{event:'*',schema:'public',table:'tasks'},()=>loadAll()).on('postgres_changes',{event:'*',schema:'public',table:'report_approvals'},()=>loadAll()).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:`recipient_id=eq.${state.user.id}`},()=>loadAll()).subscribe();}
function authBusy(b){state.authBusy=b;const btn=$('#auth-form button[type=submit]');if(btn)btn.disabled=b;}
async function login(form){authBusy(true);try{const fd=new FormData(form),email=String(fd.get('email')||'').trim();state.authEmail=email;if(!state.selectedPerson)throw Error('اختر اسمك أولًا');const {error}=await state.client.auth.signInWithOtp({email,options:{shouldCreateUser:false,emailRedirectTo:window.location.href.split('#')[0]}});if(error)throw error;state.loginSent=true;notify('راجع بريدك واضغط رابط الدخول.','success');render();}catch(e){notify('تعذّر إرسال الرابط: '+e.message,'error');}finally{authBusy(false);}}
async function markRead(){if(DEMO){state.notifications.forEach(x=>x.read_at=new Date().toISOString());persistDemo();render();return;}const {error}=await state.client.from('notifications').update({read_at:new Date().toISOString()}).eq('recipient_id',state.user.id).is('read_at',null);if(error)notify(error.message,'error');await loadAll();}
async function enableNotifications(){if(!('Notification' in window))return notify('المتصفح لا يدعم إشعارات الويب بالطريقة الحالية.','error');try{const permission=await Notification.requestPermission();notify(permission==='granted'?'تم السماح بالتنبيهات أثناء عمل الصفحة.':'لم يُسمح بتنبيهات المتصفح.');}catch(e){notify(e.message,'error');}}
function roundRect(ctx,x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function drawWrapped(ctx,text,x,y,maxWidth,lineH,{size=23,color='#272321',weight='400',max=100}={}){ctx.font=`${weight} ${size}px Tahoma, Arial, sans-serif`;ctx.fillStyle=color;ctx.textAlign='right';ctx.direction='rtl';let parts=String(text||'—').split('\n'),lines=[];for(const part of parts){let line='';for(const word of part.split(/\s+/)){let test=(line?line+' ':'')+word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word;}else line=test;}lines.push(line||' ');}let visible=lines.slice(0,max);if(lines.length>max)visible[visible.length-1]+='…';for(let i=0;i<visible.length;i++)ctx.fillText(visible[i],x,y+i*lineH);return y+visible.length*lineH;}
function buildPosterCanvas(cases){const scale=1;const canvas=document.createElement('canvas');const w=1200,pad=73,content=w-pad*2;let y=0;const sizes=[];const meas=canvas.getContext('2d');function height(text,maxwidth,size=22,lh=38,max=100){meas.font=`400 ${size}px Tahoma, Arial, sans-serif`;let lines=0;for(let p of String(text||'—').split('\n')){let line='';for(const word of p.split(/\s+/)){const test=(line?line+' ':'')+word;if(meas.measureText(test).width>maxwidth&&line){lines++;line=word;}else line=test;}lines++;}return Math.min(lines,max)*lh;}
for(const c of cases){let part=200;part+=height('الموضوع: '+short(c.claim_summary,400),content-88,23,38,4);part+=height('الجلسة السابقة: '+short(c.stage==='first'?'جلسة أولى':c.last_session_summary||'لم يُلخص بعد',600),content-88,23,38,6);part+=height('سبب الرفع: '+short(c.stage==='first'?'لا ينطبق':c.adjournment_reason||'لم يتضح من الضبط',550),content-88,23,38,6);part+=height('الإجراء القادم: '+short(c.next_action||'لم يحدد',380),content-88,23,38,5);sizes.push(Math.max(300,part+20));}
const totalHeight=Math.min(30000,400+sizes.reduce((a,b)=>a+b+26,0)+110);canvas.width=w*scale;canvas.height=totalHeight*scale;const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle='#f2f7f6';ctx.fillRect(0,0,w,totalHeight);roundRect(ctx,0,0,w,21,0,'#087967');ctx.fillStyle='#087967';ctx.textAlign='right';ctx.direction='rtl';ctx.font='bold 49px Tahoma, Arial, sans-serif';ctx.fillText('تنظيم أعمال الدائرة الرابعة',w-pad,103);ctx.font='25px Tahoma, Arial, sans-serif';ctx.fillStyle='#77695e';ctx.fillText('تقرير قضايا الجلسات اليومي',w-pad,153);ctx.textAlign='left';ctx.fillStyle='#087967';ctx.font='bold 66px Tahoma';ctx.fillText('▦',pad,120);ctx.fillStyle='#d9cabb';ctx.fillRect(pad,182,content,2);roundRect(ctx,pad,213,content,90,16,'#087967');ctx.textAlign='right';ctx.fillStyle='#fff';ctx.font='bold 30px Tahoma';ctx.fillText(hijri(state.filterDate),w-pad-25,268);ctx.textAlign='left';ctx.font='25px Tahoma';ctx.fillText(cases.length+' قضايا',pad+25,268);y=337;
for(let i=0;i<cases.length;i++){let c=cases[i],heightBox=sizes[i];if(y+heightBox>totalHeight-70)break;roundRect(ctx,pad,y,content,heightBox,17,'#ffffff');ctx.strokeStyle='#e3d9ce';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(pad,y,content,heightBox,17);ctx.stroke();ctx.textAlign='right';ctx.direction='rtl';ctx.fillStyle='#087967';ctx.font='bold 29px Tahoma';ctx.fillText(`${i+1}. ${short(c.case_type||'قضية',44)} — ${tm(c.session_time)}`,w-pad-28,y+48);ctx.fillStyle='#746d66';ctx.font='20px Tahoma';ctx.fillText(`رقم ${c.case_number}  •  ${stageTitle(c.stage)}  •  ${statusTitle(c.status)}`,w-pad-30,y+90);const parties=short(`${c.plaintiffs||'—'}   ×   ${c.defendants||'—'}`,82);ctx.fillText(parties,w-pad-30,y+124);ctx.fillStyle='#e9e1d7';ctx.fillRect(pad+25,y+145,content-50,1);let yy=y+187;const lines=[['الموضوع',short(c.claim_summary||'غير مدخل',400),4],['الجلسة السابقة',short(c.stage==='first'?'جلسة أولى':c.last_session_summary||'لم يُلخص بعد',600),6],['سبب الرفع',short(c.stage==='first'?'لا ينطبق':c.adjournment_reason||'لم يتضح من الضبط',550),6],['الإجراء القادم',short(c.next_action||'لم يحدد',380),5]];for(const [name,value,max] of lines){yy=drawWrapped(ctx,`${name}: ${value}`,w-pad-30,yy,content-60,38,{size:23,max})+10;}y+=heightBox+26;}
ctx.fillStyle='#81766e';ctx.textAlign='center';ctx.font='21px Tahoma';ctx.fillText((isReportApproved()?'تقرير معتمد • ':'تقرير غير معتمد • ')+'أعده: '+short(state.profile?.display_name||'',24)+' • المرجع: الضبط الأصلي',w/2,Math.min(y+29,totalHeight-45));return canvas;}
async function sharePng(){const cases=listForDate().filter(x=>!state.posterApprovedOnly||x.status==='approved');if(!cases.length)return;try{const canvas=buildPosterCanvas(cases);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('تعذّر إنشاء الصورة');const file=new File([blob],`تقرير-القضايا-${state.filterDate}.png`,{type:'image/png'});if(navigator.share && navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'تقرير تنظيم أعمال الدائرة الرابعة'});}else{notify('المشاركة المباشرة غير متاحة في هذا المتصفح؛ استخدم حفظ الصورة ثم أرسلها.');exportPng();}}catch(e){if(e.name!=='AbortError')notify('تعذرت مشاركة الصورة: '+e.message,'error');}}
function exportPng(){const cases=listForDate().filter(x=>!state.posterApprovedOnly||x.status==='approved');if(!cases.length)return notify('لا توجد قضايا لتصديرها.','error');try{const canvas=buildPosterCanvas(cases);canvas.toBlob(blob=>{if(!blob)return notify('لم يتمكن المتصفح من إنشاء الصورة.','error');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`تقرير-القضايا-${state.filterDate}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);notify('تم تجهيز صورة التقرير للحفظ.','success');},'image/png');}catch(e){notify('تعذر حفظ الصورة: '+e.message,'error');}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-nav],[data-action],[data-edit],[data-detail],[data-approve],[data-save],[data-stage],[data-person],[data-task-toggle],[data-task-edit],[data-task-filter]');if(!target)return;if(target.dataset.person){const choice=STAFF.find(x=>x.id===target.dataset.person);if(DEMO){state.profile=choice;localStorage.setItem('fourth-circuit-demo-profile',choice.id);notify(`مرحبًا ${choice.display_name}`,'success');render();}else{state.selectedPerson=choice.id;render();}return;}if(target.dataset.taskToggle){await toggleTask(target.dataset.taskToggle);return;}if(target.dataset.taskEdit){openTaskEditor(target.dataset.taskEdit);return;}if(target.dataset.taskFilter){state.taskFilter=target.dataset.taskFilter;render();return;}if(target.dataset.nav){navigate(target.dataset.nav);return;}if(target.dataset.edit){openEditor(target.dataset.edit);return;}if(target.dataset.detail){state.detailId=target.dataset.detail;state.showSource=false;render();return;}if(target.dataset.approve){await approveCase(target.dataset.approve);return;}if(target.dataset.save){await saveCase(target.dataset.save);return;}if(target.dataset.stage){state.stageFilter=target.dataset.stage;render();return;}const action=target.dataset.action;if(!action)return;switch(action){case 'new-case':openEditor();break;case 'new-task':openTaskEditor();break;case 'close-task-editor':closeTaskEditor();break;case 'delete-task':await deleteTask();break;case 'approve-report':await approveReport();break;case 'export-tasks':exportTasksPng();break;case 'close-editor':case 'close-detail':closeModal();break;case 'toggle-source':state.showSource=!state.showSource;render();break;case 'next-day':state.filterDate=nextWorkday();render();break;case 'summarize-local':{const out=localSummarize(state.form.previous_minutes);Object.assign(state.form,out,{summary_mode:'automatic'});render();notify('تم استخراج مسودة تحضيرية تستلزم مراجعة سبب الرفع.');break;}case 'summarize-ai':await summarizeAI();break;case 'approve-from-editor':await saveCase('approved');break;case 'delete-case':await softDeleteCase();break;case 'toggle-notifs':state.showNotifs=!state.showNotifs;render();break;case 'mark-read':await markRead();break;case 'enable-notifs':await enableNotifications();break;case 'refresh':await loadAll();notify('تم تحديث البيانات من القاعدة.','success');break;case 'refresh-profile':await refreshProfile();break;case 'logout':if(DEMO){state.profile=null;localStorage.removeItem('fourth-circuit-demo-profile');render();}else await state.client?.auth.signOut();break;case 'toggle-auth':state.authMode=state.authMode==='login'?'signup':'login';render();break;case 'export-png':exportPng();break;case 'share-png':await sharePng();break;}});
document.addEventListener('input',e=>{if(e.target.dataset.formField&&state.form){state.form[e.target.dataset.formField]=e.target.value;}if(e.target.dataset.taskField&&state.taskForm){state.taskForm[e.target.dataset.taskField]=e.target.value;}if(e.target.matches('[data-task-search]')){state.taskSearch=e.target.value;const list=$('.tasks-list');if(list){const temp=state.taskSearch;state.taskSearch=temp;list.innerHTML=state.tasks.filter(t=>!t.deleted_at&&(state.taskFilter==='all'||t.status===state.taskFilter)&&[t.title,t.details,t.case_number,profileName(t.created_by)].join(' ').includes(temp)).map(taskRow).join('')||'<div class="card empty">لا توجد نتائج</div>';}}if(e.target.matches('[data-search]')){state.search=e.target.value;const list=$('.cases-list');if(list)list.innerHTML=filteredCases().length?filteredCases().map(caseRow).join(''):emptyState();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter-date]')){state.filterDate=e.target.value;render();}if(e.target.matches('[data-approved-only]')){state.posterApprovedOnly=e.target.checked;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();login(e.target);}if(e.target.id==='case-form'){e.preventDefault();saveCase('ready');}if(e.target.id==='task-form'){e.preventDefault();saveTask();}});
init();
